function fcStop() { clearInterval(fc.t); fc.t = 0; }
function fcSet(min) { fcStop(); fc.total = fc.left = min * 60; document.querySelectorAll('[data-fc]').forEach(b => b.setAttribute('aria-pressed', +b.dataset.fc === min)); fcRender(); }
