(function(){var app=document.querySelector('.app'),off=false;try{off=localStorage.getItem('side')==='off'}catch(e){}
function set(v){off=v;app.classList.toggle('side-off',v);document.querySelectorAll('[data-side]').forEach(function(b){b.setAttribute('aria-expanded',String(!v))});try{localStorage.setItem('side',v?'off':'on')}catch(e){}}
set(off);document.addEventListener('click',function(e){if(e.target.closest('[data-side]'))set(!off)});
document.addEventListener('keydown',function(e){if((e.ctrlKey||e.metaKey)&&e.key==='b'){e.preventDefault();set(!off)}})})();
